-- packed Lua; runtime requires loadstring or load
local data=[==[]==]
local abc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lookup={} for i=1,#abc do lookup[abc:sub(i,i)]=i-1 end
local bytes={} local n=0 local acc=0 local bits=0
for i=1,#data do local x=lookup[data:sub(i,i)] if x then acc=acc*64+x;bits=bits+6;if bits>=8 then bits=bits-8;n=n+1;bytes[n]=string.char(math.floor(acc/2^bits)%256);acc=acc%2^bits end end end
local raw=table.concat(bytes)
local dict={} for i=0,255 do dict[i]=string.char(i) end
local nextcode=256 local old=nil local chunks={} local count=0
for i=1,#raw,2 do
 local code=raw:byte(i)*256+raw:byte(i+1)
 local entry=dict[code]
 if not entry then assert(code==nextcode and old,"invalid packed data");entry=old..old:sub(1,1) end
 count=count+1;chunks[count]=entry
 if old then
  if nextcode<65535 then dict[nextcode]=old..entry:sub(1,1);nextcode=nextcode+1
  else dict={} for j=0,255 do dict[j]=string.char(j) end;nextcode=256 end
 end
 old=entry
end
local source=table.concat(chunks)
local loader=loadstring or load
return assert(loader(source))()
